<?php
function customer_module_fields(array $p,array $selection=[]): void {
    if(isset($p['_quote_id']))return;$allModules=product_modules((int)$p['id']);$modules=array_values(array_filter($allModules,fn($m)=>!module_is_included($m)));$included=array_values(array_filter($p['_module_selection']??[],fn($l)=>!empty($l['included'])));if($included)echo '<section class="package-config"><h3>Im Grundpreis enthalten</h3><p class="pre-wrap">'.e(module_description($included)).'</p></section>';if(!$modules)return;$base=$p['_base_product']??$p;$tax=product_tax($base);?>
    <section class="module-configurator" data-module-configurator data-separate-billing="<?= billing_months($p['billing']) && product_sale_mode($base)==='direct'?'1':'0' ?>" data-base-profile="<?= e(json_encode(module_customer_base_profile($p))) ?>" data-base-net="<?= (int)$tax['net_cents'] ?>" data-base-unknown="<?= $base['price_cents']===null?'1':'0' ?>" data-billing="<?= e(cycle($p['billing'])) ?>"><h3>Dein Paket zusammenstellen</h3><p>Grundpreis: <?= $p['price_cents']===null?'auf Anfrage':money($tax['gross_cents']).' inkl. 19 % MwSt.' ?> / <?= cycle($p['billing']) ?>. Wähle deine zusätzlichen Module.</p>
    <?php foreach($modules as $m):$qty=$selection[$m['id']]??$m['default_qty']; ?><label class="field module-choice"><span><strong><?= e($m['label']) ?></strong><?php if($m['description']): ?><small><?= e($m['description']) ?></small><?php endif ?><small><?php if($m['control']==='select'): ?>Preis je Auswahloption · inkl. 19 % MwSt.<?php else: ?><?= money(vat_from_net((int)$m['net_cents'])['gross_cents']) ?> inkl. 19 % MwSt. (<?= money($m['net_cents']) ?> netto) / <?= e(module_is_storage_target($m['target'])?'Moduleinheit':($m['unit_label']?:'Option')) ?> / <?= cycle($p['billing']) ?><?php endif ?></small><?php if(module_is_storage_target($m['target'])): ?><small>Eine Moduleinheit: <?= e(module_storage_increment_text($m)) ?></small><?php endif ?></span>
    <?php if($m['control']==='select'): ?><select name="modules[<?= (int)$m['id'] ?>]" data-module-quantity data-target="<?= e($m['target']) ?>" data-unit-value="<?= (int)$m['unit_value'] ?>" data-net="0" data-label="<?= e($m['label']) ?>" data-unit=""><option value="0" data-net="0">Nicht gewählt</option><?php foreach($m['options'] as $optionId=>$option): ?><option value="<?= (int)$optionId ?>" data-net="<?= (int)$option['net_cents'] ?>" data-option-label="<?= e($option['label']) ?>" data-technical-value="<?= e($option['value']) ?>" <?= (int)$qty===(int)$optionId?'selected':'' ?>><?= e($option['label']) ?> · <?= money(vat_from_net((int)$option['net_cents'])['gross_cents']) ?> inkl. MwSt.</option><?php endforeach ?></select><?php elseif($m['control']==='checkbox'): ?><input type="hidden" name="modules[<?= (int)$m['id'] ?>]" value="0"><input type="checkbox" name="modules[<?= (int)$m['id'] ?>]" value="1" data-module-quantity data-target="<?= e($m['target']) ?>" data-unit-value="<?= (int)$m['unit_value'] ?>" data-net="<?= (int)$m['net_cents'] ?>" data-label="<?= e($m['label']) ?>" data-unit="<?= e($m['unit_label']) ?>" <?= (int)$qty?'checked':'' ?>><?php else: ?><input type="number" name="modules[<?= (int)$m['id'] ?>]" min="<?= (int)$m['min_qty'] ?>" <?= (int)$m['max_qty']>0?'max="'.(int)$m['max_qty'].'"':'' ?> step="1" required value="<?= (int)$qty ?>" data-module-quantity data-target="<?= e($m['target']) ?>" data-unit-value="<?= (int)$m['unit_value'] ?>" data-net="<?= (int)$m['net_cents'] ?>" data-label="<?= e($m['label']) ?>" data-unit="<?= e($m['unit_label']) ?>"><?php endif ?></label><?php endforeach ?>
    <div class="module-total" aria-live="polite"><span><?= $base['price_cents']===null?'Zusatzmodule netto':'Gesamt netto' ?>: <strong data-module-net></strong></span><span>19 % MwSt.: <strong data-module-tax></strong></span><span><?= $base['price_cents']===null?'Zusatzmodule brutto zzgl. Grundpreis auf Anfrage':'Gesamt' ?> / <?= cycle($p['billing']) ?>: <strong data-module-gross></strong></span></div><div class="module-description"><h4>Gewählte Zusatzleistungen</h4><ul data-module-description></ul></div></section>
    <?php
}
function domain_recommendation_cards(int $product,string $domain): void {
    $rows=domain_recommendations($product);if(!$rows)return;?>
    <section class="domain-recommendations panel form-panel"><h2>Optional: Webspace oder VPS zu deiner Domain</h2><p>Du kannst die Domain eigenständig nutzen. Ein zusätzliches Paket ist freiwillig und wird separat bestellt.</p><div class="service-grid"><?php foreach($rows as $p): ?><article class="service-card"><h3><?= e($p['name']) ?></h3><p><?= e($p['description']) ?></p><p><strong><?= price($p) ?></strong><?= $p['price_cents']!==null?' / '.cycle($p['billing']).' inkl. 19 % MwSt.':'' ?></p><a class="button button-outline" href="<?= package_is_fixed($p)?'/bestellen':'/konfigurieren' ?>?produkt=<?= e($p['slug']) ?>&domain=<?= e(rawurlencode($domain)) ?>"><?= package_is_fixed($p)?'Paket konfigurieren':'Paket anfragen' ?></a></article><?php endforeach ?></div></section><?php
}
